async function c(a){let u=a.main,s=document.getElementById("sel"),m=document.getElementById("log-single");s&&m&&s.addEventListener("is-change",t=>{let l=t.detail;m.textContent=`value: ${l.value||"\u2014"}`});let n=document.getElementById("multi"),i=document.getElementById("log-multi");if(n&&i){let t=()=>{i.textContent=`values: ${(n.values??[]).join(", ")||"\u2014"}`};n.addEventListener("is-change",t),t()}let e=document.getElementById("demo-form"),o=document.getElementById("log-form");e&&o&&(e.addEventListener("submit",t=>{t.preventDefault();let l=[...new FormData(e).entries()].map(([d,r])=>`${d}=${r}`);o.textContent=`FormData: ${l.join(" \xB7 ")||"vac\xEDo"}`}),e.addEventListener("reset",()=>{o.textContent="FormData: \u2014"}))}function v(){}export{c as mount,v as unmount};
